import React, { useState } from 'react';
import { Input, Select, DatePicker, Card, Button, Tag } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import { airports } from '../FlightSearch/data/airports';
import dayjs from 'dayjs';
import { useHybridPathInput } from '../../hooks/useHybridPathInput';
import '../../styles/NormalRouteSearch.css';

const { RangePicker } = DatePicker;

const NormalRouteSearch = ({ onSearch }) => {
  const {
    path,
    showAirportSelect,
    currentInput,
    selectedAirport,
    inputRef,
    airportOptions,
    handleInputChange,
    handleAirportSelect,
    handleKeyDown,
    setPath
  } = useHybridPathInput();

  const [excludedSources, setExcludedSources] = useState([]);
  const [apiKey, setApiKey] = useState('');
  const [dateRange, setDateRange] = useState(null);
  const [error, setError] = useState('');
  const [isSearching, setIsSearching] = useState(false);

  // Convert airports data to select options for excluded sources
  const airportOptionsForExcluded = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name} (${airport.Country})`
  }));

  // Handle search submission
  const handleSearch = () => {
    if (!path) {
      setError('Please enter a path');
      return;
    }

    if (!apiKey) {
      setError('Please enter an API key');
      return;
    }

    if (!dateRange) {
      setError('Please select a date range');
      return;
    }

    setIsSearching(true);
    setError('');

    // Parse the path into segments
    const segments = path.split('-').map(segment => {
      const airports = segment.split('/');
      return {
        airports: airports.map(code => code.trim()),
        isOptional: airports.length > 1
      };
    });

    onSearch({
      path: segments,
      excludedSources,
      apiKey,
      dateRange: {
        startDate: dateRange[0].format('YYYY-MM-DD'),
        endDate: dateRange[1].format('YYYY-MM-DD')
      }
    });
  };

  // Custom tag render for airport boxes
  const tagRender = (props) => {
    const { label, value, closable, onClose } = props;
    return (
      <Tag
        color="#ffffff"
        closable={closable}
        onClose={onClose}
        closeIcon={<span style={{ color: '#666666' }}>×</span>}
        style={{ 
          display: 'inline-flex', 
          alignItems: 'center', 
          marginRight: 4,
          fontFamily: 'Menlo, Monaco, Consolas, monospace',
          padding: '2px 7px',
          color: '#000000',
          border: '1px solid #000000'
        }}
      >
        {value}
      </Tag>
    );
  };

  return (
    <Card className="search-form">
      {/* Path Input */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Path
        </label>
        <div className="relative">
          <Select
            mode="multiple"
            value={path ? path.split('-').map(segment => segment.split('/')[0].trim()) : []}
            onChange={(values) => {
              const newPath = values.join('-');
              setPath(newPath);
            }}
            options={airportOptions}
            placeholder="Enter path (e.g., NRT/HND-OAK/SFO-JFK/EWR)"
            className="w-full"
            showSearch
            filterOption={(input, option) =>
              (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
            }
            optionRender={(option) => (
              <div className="airport-option">
                <span className="airport-code">{option.value}</span>
                <span className="airport-name">{option.label}</span>
              </div>
            )}
            tagRender={tagRender}
            suffixIcon={null}
            searchValue={currentInput}
            onSearch={handleInputChange}
            onKeyDown={handleKeyDown}
            ref={inputRef}
            status={error && !path ? 'error' : ''}
          />
          {error && !path && (
            <div className="text-red-500 text-sm mt-1">{error}</div>
          )}
        </div>
      </div>

      {/* Excluded Sources */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Sources Excluded
        </label>
        <Select
          mode="multiple"
          value={excludedSources}
          onChange={setExcludedSources}
          options={airportOptionsForExcluded}
          placeholder="Select airports to exclude"
          className="w-full"
          showSearch
          filterOption={(input, option) =>
            (option?.label ?? '').toLowerCase().includes(input.toLowerCase())
          }
          optionRender={(option) => (
            <div className="airport-option">
              <span className="airport-code">{option.value}</span>
              <span className="airport-name">{option.label}</span>
            </div>
          )}
          tagRender={tagRender}
        />
      </div>

      {/* API Key */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          API Key
        </label>
        <Input.Password
          value={apiKey}
          onChange={(e) => setApiKey(e.target.value)}
          placeholder="Enter your API key"
          className="w-full"
          status={error && !apiKey ? 'error' : ''}
        />
        {error && !apiKey && (
          <div className="text-red-500 text-sm mt-1">{error}</div>
        )}
      </div>

      {/* Date Range */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Date Range
        </label>
        <RangePicker
          value={dateRange}
          onChange={setDateRange}
          className="w-full"
          status={error && !dateRange ? 'error' : ''}
        />
        {error && !dateRange && (
          <div className="text-red-500 text-sm mt-1">{error}</div>
        )}
      </div>

      {/* Search Button */}
      <Button
        type="primary"
        icon={<SearchOutlined />}
        onClick={handleSearch}
        loading={isSearching}
        className="w-full mt-4"
      >
        Search
      </Button>
    </Card>
  );
};

export default NormalRouteSearch;
